//! Proxy-manager domain model.
//!
//! The model is certificate- and host-centric. It enforces the separation between:
//!
//! * [`CertificateOrigin::AutoGenerated`] — CertMagic-style dynamic/eager certificates owned by an
//!   [`AutoCertificatePolicy`];
//! * [`CertificateOrigin::Manual`] — user-uploaded PEM material;
//! * [`CertificateOrigin::AcmeConfigured`] — an explicit ACME certificate request;
//! * [`CertificateOrigin::InternalCa`] — an explicit internal-CA certificate.
//!
//! The model never contains private-key bytes. Manual keys belong in the secret store; auto and
//! ACME keys never leave the core certificate storage. The host layer adds proxy, redirect and dead
//! specs with structural validation; route compilation lives in `caddy-rs-pm-compiler`.

#![forbid(unsafe_code)]

use std::collections::{BTreeMap, BTreeSet};
use std::fmt;

use serde::{Deserialize, Serialize};
use thiserror::Error;

/// Why a certificate exists and who owns its lifecycle.
#[derive(Debug, Clone, Copy, PartialEq, Eq, Hash, Serialize, Deserialize)]
#[serde(rename_all = "snake_case")]
pub enum CertificateOrigin {
    /// Issued by a core dynamic-certificate manager from an `AutoCertificatePolicy`.
    AutoGenerated,
    /// Uploaded by a user. The only origin where the PM holds private-key material.
    Manual,
    /// Explicitly requested from an ACME issuer for fixed domains.
    AcmeConfigured,
    /// Explicitly requested from the internal CA.
    InternalCa,
}

impl CertificateOrigin {
    pub fn as_str(self) -> &'static str {
        match self {
            Self::AutoGenerated => "auto_generated",
            Self::Manual => "manual",
            Self::AcmeConfigured => "acme_configured",
            Self::InternalCa => "internal_ca",
        }
    }

    /// Human label used by the API/UI.
    pub fn label(self) -> &'static str {
        match self {
            Self::AutoGenerated => "Auto-generated",
            Self::Manual => "Manual",
            Self::AcmeConfigured => "ACME (configured)",
            Self::InternalCa => "Internal CA",
        }
    }

    pub fn is_auto_generated(self) -> bool {
        matches!(self, Self::AutoGenerated)
    }

    /// Auto-generated certificates are selected by policy, never by certificate id.
    pub fn bindable_by_id(self) -> bool {
        !self.is_auto_generated()
    }
}

impl fmt::Display for CertificateOrigin {
    fn fmt(&self, formatter: &mut fmt::Formatter<'_>) -> fmt::Result {
        formatter.write_str(self.as_str())
    }
}

#[derive(Debug, Clone, Copy, PartialEq, Eq, Hash, Serialize, Deserialize)]
#[serde(transparent)]
pub struct CertificateId(pub u64);

#[derive(Debug, Clone, Copy, PartialEq, Eq, Hash, Serialize, Deserialize)]
#[serde(transparent)]
pub struct PolicyId(pub u64);

#[derive(Debug, Clone, Copy, PartialEq, Eq, Serialize, Deserialize)]
#[serde(rename_all = "snake_case")]
pub enum CertificateStatus {
    Pending,
    Issued,
    Renewing,
    Failed,
    Revoked,
    /// A policy covers the host but no certificate has been observed yet.
    Missing,
}

impl CertificateStatus {
    pub fn is_usable(self) -> bool {
        matches!(self, Self::Issued | Self::Renewing)
    }
}

#[derive(Debug, Clone, Copy, PartialEq, Eq, Serialize, Deserialize)]
#[serde(rename_all = "snake_case")]
pub enum AutoMode {
    /// Issued lazily at handshake time by the core on-demand manager.
    OnDemand,
    /// Issued eagerly when the policy is applied.
    Eager,
}

#[derive(Debug, Clone, Copy, PartialEq, Eq, Serialize, Deserialize)]
#[serde(rename_all = "snake_case")]
pub enum KeyType {
    Rsa2048,
    Rsa4096,
    P256,
    P384,
    Ed25519,
}

impl KeyType {
    pub fn as_str(self) -> &'static str {
        match self {
            Self::Rsa2048 => "rsa2048",
            Self::Rsa4096 => "rsa4096",
            Self::P256 => "p256",
            Self::P384 => "p384",
            Self::Ed25519 => "ed25519",
        }
    }

    pub fn parse(value: &str) -> Result<Self, CoreError> {
        match value {
            "rsa2048" => Ok(Self::Rsa2048),
            "rsa4096" => Ok(Self::Rsa4096),
            "p256" => Ok(Self::P256),
            "p384" => Ok(Self::P384),
            "ed25519" => Ok(Self::Ed25519),
            other => Err(CoreError::Invalid(format!(
                "unsupported key type `{other}`; expected rsa2048, rsa4096, p256, p384 or ed25519"
            ))),
        }
    }
}

/// A policy that owns auto-generated certificates.
#[derive(Debug, Clone, PartialEq, Serialize, Deserialize)]
pub struct AutoCertificatePolicy {
    pub id: PolicyId,
    pub name: String,
    /// Exact names and left-most-label wildcard patterns (`*.example.com`).
    pub subjects: Vec<String>,
    pub mode: AutoMode,
    /// Optional issuer/profile name. `None` means the core default issuer.
    pub issuer: Option<String>,
    pub key_type: Option<KeyType>,
    /// Renew when this fraction of lifetime remains (0.0–1.0).
    pub renewal_window_ratio: Option<f64>,
    pub enabled: bool,
}

impl AutoCertificatePolicy {
    pub fn validate(&self) -> Result<(), CoreError> {
        if self.id.0 == 0 {
            return Err(CoreError::Invalid(
                "policy id must be greater than zero".to_string(),
            ));
        }
        require_non_empty("policy name", &self.name, 120)?;
        if self.subjects.is_empty() {
            return Err(CoreError::Invalid(
                "an auto-certificate policy needs at least one subject".to_string(),
            ));
        }
        if self.subjects.len() > 100 {
            return Err(CoreError::Invalid(
                "an auto-certificate policy supports at most 100 subjects".to_string(),
            ));
        }
        let mut seen = BTreeSet::new();
        for subject in &self.subjects {
            let normalized = normalize_pattern(subject)?;
            if !seen.insert(normalized.clone()) {
                return Err(CoreError::Invalid(format!(
                    "duplicate subject `{normalized}`"
                )));
            }
        }
        if let Some(ratio) = self.renewal_window_ratio {
            if !(0.0..1.0).contains(&ratio) {
                return Err(CoreError::Invalid(
                    "renewal_window_ratio must be greater than 0 and less than 1".to_string(),
                ));
            }
        }
        Ok(())
    }

    /// Whether this policy can issue for `name`. Wildcard patterns match exactly one label.
    pub fn matches(&self, name: &str) -> bool {
        let Ok(name) = normalize_pattern(name) else {
            return false;
        };
        self.subjects
            .iter()
            .any(|subject| pattern_covers(subject, &name))
    }

    pub fn covers_all(&self, domains: &[String]) -> bool {
        !domains.is_empty() && domains.iter().all(|domain| self.matches(domain))
    }

    pub fn display_name(&self) -> String {
        format!("Auto-generated — {}", self.name)
    }
}

/// Explicit certificate metadata. No private-key bytes are stored in this type.
#[derive(Debug, Clone, PartialEq, Serialize, Deserialize)]
pub struct ExplicitCertificate {
    pub id: CertificateId,
    /// Manual, ACME-configured or internal-CA.
    pub origin: CertificateOrigin,
    pub domains: Vec<String>,
    pub status: CertificateStatus,
    pub expires_at_unix: Option<i64>,
    /// Storage key/path managed by the certificate service (never a private-key value).
    pub storage_ref: Option<String>,
}

impl ExplicitCertificate {
    pub fn validate(&self) -> Result<(), CoreError> {
        if self.id.0 == 0 {
            return Err(CoreError::Invalid(
                "certificate id must be greater than zero".to_string(),
            ));
        }
        if !self.origin.bindable_by_id() {
            return Err(CoreError::Invalid(format!(
                "{} certificates cannot be explicit certificate records",
                self.origin.label()
            )));
        }
        validate_certificate_domains(&self.domains)?;
        if self.origin == CertificateOrigin::Manual && self.storage_ref.is_none() {
            return Err(CoreError::Invalid(
                "manual certificates require a storage reference".to_string(),
            ));
        }
        Ok(())
    }

    pub fn covers_all(&self, host_domains: &[String]) -> bool {
        !host_domains.is_empty()
            && host_domains
                .iter()
                .all(|domain| certificate_covers(&self.domains, domain))
    }
}

/// A discovered auto-generated certificate. It is a read-only projection, not a user-created
/// certificate row.
#[derive(Debug, Clone, PartialEq, Serialize, Deserialize)]
pub struct AutoCertificate {
    /// Stable projection id, for example `auto:4:api.example.com`.
    pub uid: String,
    pub policy_id: PolicyId,
    pub domains: Vec<String>,
    pub status: CertificateStatus,
    pub expires_at_unix: Option<i64>,
    /// Where the core certificate service keeps the certificate, if observed.
    pub storage_ref: Option<String>,
}

impl AutoCertificate {
    pub fn validate(&self) -> Result<(), CoreError> {
        require_non_empty("auto certificate uid", &self.uid, 255)?;
        if self.policy_id.0 == 0 {
            return Err(CoreError::Invalid(
                "auto certificate policy id must be greater than zero".to_string(),
            ));
        }
        validate_certificate_domains(&self.domains)?;
        Ok(())
    }

    pub fn display_name(&self) -> String {
        format!("Auto-generated — {}", self.domains.join(", "))
    }

    pub fn read_only(&self) -> bool {
        true
    }
}

/// API/read-model projection with an explicit `origin` field. The persisted record types carry
/// their own invariants; this is what the certificate list endpoint returns. It is an output-only
/// projection: do not deserialize untrusted input into it without calling the record validators.
#[derive(Debug, Clone, PartialEq, Serialize, Deserialize)]
pub struct CertificateView {
    pub origin: CertificateOrigin,
    pub uid: String,
    pub domains: Vec<String>,
    pub status: CertificateStatus,
    pub expires_at_unix: Option<i64>,
    pub policy_id: Option<PolicyId>,
    pub read_only: bool,
    pub display_name: String,
}

/// Unified read model. Mutations must branch on [`CertificateRecord::origin`].
#[derive(Debug, Clone, PartialEq, Serialize, Deserialize)]
#[serde(untagged)]
pub enum CertificateRecord {
    Auto(AutoCertificate),
    Explicit(ExplicitCertificate),
}

impl CertificateRecord {
    pub fn origin(&self) -> CertificateOrigin {
        match self {
            Self::Auto(_) => CertificateOrigin::AutoGenerated,
            Self::Explicit(certificate) => certificate.origin,
        }
    }

    pub fn domains(&self) -> &[String] {
        match self {
            Self::Auto(certificate) => &certificate.domains,
            Self::Explicit(certificate) => &certificate.domains,
        }
    }

    pub fn status(&self) -> CertificateStatus {
        match self {
            Self::Auto(certificate) => certificate.status,
            Self::Explicit(certificate) => certificate.status,
        }
    }

    pub fn is_read_only(&self) -> bool {
        self.origin().is_auto_generated()
    }

    pub fn display_name(&self) -> String {
        match self {
            Self::Auto(certificate) => certificate.display_name(),
            Self::Explicit(certificate) => {
                format!(
                    "{} — {}",
                    certificate.origin.label(),
                    certificate.domains.join(", ")
                )
            }
        }
    }

    pub fn validate(&self) -> Result<(), CoreError> {
        match self {
            Self::Auto(certificate) => certificate.validate(),
            Self::Explicit(certificate) => certificate.validate(),
        }
    }

    pub fn view(&self) -> CertificateView {
        match self {
            Self::Auto(certificate) => CertificateView {
                origin: CertificateOrigin::AutoGenerated,
                uid: certificate.uid.clone(),
                domains: certificate.domains.clone(),
                status: certificate.status,
                expires_at_unix: certificate.expires_at_unix,
                policy_id: Some(certificate.policy_id),
                read_only: true,
                display_name: certificate.display_name(),
            },
            Self::Explicit(certificate) => CertificateView {
                origin: certificate.origin,
                uid: certificate.id.0.to_string(),
                domains: certificate.domains.clone(),
                status: certificate.status,
                expires_at_unix: certificate.expires_at_unix,
                policy_id: None,
                read_only: false,
                display_name: format!(
                    "{} — {}",
                    certificate.origin.label(),
                    certificate.domains.join(", ")
                ),
            },
        }
    }
}

#[derive(Debug, Clone, Copy, PartialEq, Eq, Serialize, Deserialize)]
#[serde(rename_all = "snake_case")]
pub enum TlsMode {
    Disabled,
    Auto,
    Manual,
    AcmeConfigured,
    InternalCa,
}

impl TlsMode {
    pub fn origin(self) -> Option<CertificateOrigin> {
        match self {
            Self::Disabled => None,
            Self::Auto => Some(CertificateOrigin::AutoGenerated),
            Self::Manual => Some(CertificateOrigin::Manual),
            Self::AcmeConfigured => Some(CertificateOrigin::AcmeConfigured),
            Self::InternalCa => Some(CertificateOrigin::InternalCa),
        }
    }

    pub fn from_origin(origin: CertificateOrigin) -> Self {
        match origin {
            CertificateOrigin::AutoGenerated => Self::Auto,
            CertificateOrigin::Manual => Self::Manual,
            CertificateOrigin::AcmeConfigured => Self::AcmeConfigured,
            CertificateOrigin::InternalCa => Self::InternalCa,
        }
    }
}

/// The TLS binding on a host. Exactly one mode is active.
#[derive(Debug, Clone, PartialEq, Eq, Serialize, Deserialize)]
pub struct HostTls {
    pub mode: TlsMode,
    pub certificate_id: Option<CertificateId>,
    pub auto_policy_id: Option<PolicyId>,
    pub ssl_forced: bool,
    pub hsts_enabled: bool,
    pub hsts_subdomains: bool,
}

impl HostTls {
    pub fn disabled() -> Self {
        Self {
            mode: TlsMode::Disabled,
            certificate_id: None,
            auto_policy_id: None,
            ssl_forced: false,
            hsts_enabled: false,
            hsts_subdomains: false,
        }
    }

    pub fn for_auto(policy_id: PolicyId) -> Self {
        Self {
            mode: TlsMode::Auto,
            certificate_id: None,
            auto_policy_id: Some(policy_id),
            ssl_forced: true,
            hsts_enabled: false,
            hsts_subdomains: false,
        }
    }

    pub fn for_explicit(certificate_id: CertificateId, origin: CertificateOrigin) -> Self {
        Self {
            mode: TlsMode::from_origin(origin),
            certificate_id: Some(certificate_id),
            auto_policy_id: None,
            ssl_forced: true,
            hsts_enabled: false,
            hsts_subdomains: false,
        }
    }

    /// Validate the binding's own fields without loading a certificate or policy.
    ///
    /// This is the structural half of [`HostTls::validate`]: TLS mode/reference consistency and
    /// the HSTS/forced-SSL invariants. Coverage is checked by [`HostTls::validate`].
    pub fn validate_shape(&self) -> Result<(), CoreError> {
        if self.hsts_subdomains && !self.hsts_enabled {
            return Err(CoreError::Invalid(
                "hsts_subdomains requires hsts_enabled".to_string(),
            ));
        }
        if self.hsts_enabled && !self.ssl_forced {
            return Err(CoreError::Invalid(
                "hsts_enabled requires ssl_forced".to_string(),
            ));
        }
        match self.mode {
            TlsMode::Disabled => {
                if self.certificate_id.is_some() || self.auto_policy_id.is_some() {
                    return Err(CoreError::Invalid(
                        "disabled TLS cannot reference a certificate or policy".to_string(),
                    ));
                }
                if self.ssl_forced || self.hsts_enabled || self.hsts_subdomains {
                    return Err(CoreError::Invalid(
                        "disabled TLS cannot force SSL or HSTS".to_string(),
                    ));
                }
            }
            TlsMode::Auto => {
                if self.certificate_id.is_some() {
                    return Err(CoreError::Invalid(
                        "auto TLS must not carry a certificate id".to_string(),
                    ));
                }
                if self.auto_policy_id.is_none() {
                    return Err(CoreError::Missing("auto_policy_id"));
                }
            }
            TlsMode::Manual | TlsMode::AcmeConfigured | TlsMode::InternalCa => {
                if self.auto_policy_id.is_some() {
                    return Err(CoreError::Invalid(
                        "explicit TLS must not carry an auto policy id".to_string(),
                    ));
                }
                if self.certificate_id.is_none() {
                    return Err(CoreError::Missing("certificate_id"));
                }
            }
        }
        Ok(())
    }

    /// Validate the binding against the host domains and the referenced objects.
    ///
    /// `certificate` and `policy` must be `None` when the mode does not reference them; this is
    /// checked to prevent cross-origin assignment.
    pub fn validate(
        &self,
        host_domains: &[String],
        certificate: Option<&ExplicitCertificate>,
        policy: Option<&AutoCertificatePolicy>,
    ) -> Result<(), CoreError> {
        validate_pattern_domains(host_domains)?;
        self.validate_shape()?;

        match self.mode {
            TlsMode::Disabled => {
                if certificate.is_some() || policy.is_some() {
                    return Err(CoreError::Invalid(
                        "disabled TLS must not be validated with a certificate or policy"
                            .to_string(),
                    ));
                }
            }
            TlsMode::Auto => {
                if certificate.is_some() {
                    return Err(CoreError::Invalid(
                        "auto TLS must not be validated with an explicit certificate".to_string(),
                    ));
                }
                let policy_id = self
                    .auto_policy_id
                    .ok_or(CoreError::Missing("auto_policy_id"))?;
                let Some(policy) = policy else {
                    return Err(CoreError::Missing("auto certificate policy"));
                };
                if policy.id != policy_id {
                    return Err(CoreError::Invalid(format!(
                        "host references auto policy {} but the loaded policy is {}",
                        policy_id.0, policy.id.0
                    )));
                }
                if !policy.enabled {
                    return Err(CoreError::Invalid(format!(
                        "auto certificate policy {} is disabled",
                        policy_id.0
                    )));
                }
                policy.validate()?;
                let missing: Vec<_> = host_domains
                    .iter()
                    .filter(|domain| !policy.matches(domain))
                    .cloned()
                    .collect();
                if !missing.is_empty() {
                    return Err(CoreError::Coverage {
                        origin: CertificateOrigin::AutoGenerated,
                        domains: missing,
                    });
                }
            }
            TlsMode::Manual | TlsMode::AcmeConfigured | TlsMode::InternalCa => {
                if policy.is_some() {
                    return Err(CoreError::Invalid(
                        "explicit TLS must not be validated with an auto policy".to_string(),
                    ));
                }
                let certificate_id = self
                    .certificate_id
                    .ok_or(CoreError::Missing("certificate_id"))?;
                let Some(certificate) = certificate else {
                    return Err(CoreError::Missing("certificate"));
                };
                if certificate.id != certificate_id {
                    return Err(CoreError::Invalid(format!(
                        "host references certificate {} but the loaded certificate is {}",
                        certificate_id.0, certificate.id.0
                    )));
                }
                certificate.validate()?;
                let expected = self.mode.origin().expect("explicit mode");
                if certificate.origin != expected {
                    return Err(CoreError::OriginMismatch {
                        expected,
                        actual: certificate.origin,
                    });
                }
                if !certificate.covers_all(host_domains) {
                    let missing: Vec<_> = host_domains
                        .iter()
                        .filter(|domain| !certificate_covers(&certificate.domains, domain))
                        .cloned()
                        .collect();
                    return Err(CoreError::Coverage {
                        origin: certificate.origin,
                        domains: missing,
                    });
                }
            }
        }
        Ok(())
    }
}

/// Stable proxy-manager host identifier.
#[derive(Debug, Clone, Copy, PartialEq, Eq, PartialOrd, Ord, Hash, Serialize, Deserialize)]
pub struct HostId(pub u64);

impl HostId {
    pub fn new(value: u64) -> Result<Self, CoreError> {
        if value == 0 {
            return Err(CoreError::Invalid(
                "host id must be greater than zero".to_string(),
            ));
        }
        Ok(Self(value))
    }
}

/// The three HTTP host classes supported by the first compiler slice.
#[derive(Debug, Clone, Copy, PartialEq, Eq, Serialize, Deserialize)]
#[serde(rename_all = "snake_case")]
pub enum HostKind {
    Proxy,
    Redirect,
    Dead,
}

impl HostKind {
    pub fn as_str(self) -> &'static str {
        match self {
            Self::Proxy => "proxy",
            Self::Redirect => "redirect",
            Self::Dead => "dead",
        }
    }
}

/// Upstream scheme for a proxy host.
#[derive(Debug, Clone, Copy, PartialEq, Eq, Serialize, Deserialize)]
#[serde(rename_all = "snake_case")]
pub enum UpstreamScheme {
    Http,
    Https,
}

impl UpstreamScheme {
    pub fn as_str(self) -> &'static str {
        match self {
            Self::Http => "http",
            Self::Https => "https",
        }
    }
}

/// A validated proxy upstream.
#[derive(Debug, Clone, PartialEq, Eq, Serialize, Deserialize)]
pub struct Upstream {
    pub scheme: UpstreamScheme,
    pub host: String,
    pub port: u16,
}

impl Upstream {
    pub fn new(scheme: UpstreamScheme, host: impl Into<String>, port: u16) -> Self {
        Self {
            scheme,
            host: host.into(),
            port,
        }
    }

    pub fn validate(&self) -> Result<(), CoreError> {
        require_non_empty("upstream host", &self.host, 255)?;
        if self.host.trim() != self.host {
            return Err(CoreError::Invalid(
                "upstream host must not have leading or trailing whitespace".to_string(),
            ));
        }
        if self.host.contains("://")
            || self.host.contains('/')
            || self.host.contains('\\')
            || self.host.chars().any(char::is_whitespace)
        {
            return Err(CoreError::Invalid(format!(
                "upstream host `{}` must be a hostname or IP address without a scheme or path",
                self.host
            )));
        }
        if self.host.contains(':') {
            let candidate = self
                .host
                .strip_prefix('[')
                .and_then(|value| value.strip_suffix(']'))
                .unwrap_or(&self.host);
            candidate.parse::<std::net::Ipv6Addr>().map_err(|_| {
                CoreError::Invalid(format!(
                    "upstream host `{}` contains ':' but is not a valid IPv6 address",
                    self.host
                ))
            })?;
        }
        if self.port == 0 {
            return Err(CoreError::Invalid(
                "upstream port must be between 1 and 65535".to_string(),
            ));
        }
        Ok(())
    }

    /// The Caddy `dial` form: `scheme://host:port`, with IPv6 literals bracketed.
    pub fn dial(&self) -> String {
        let host = if self.host.contains(':') && !self.host.starts_with('[') {
            format!("[{}]", self.host)
        } else {
            self.host.clone()
        };
        format!("{}://{}:{}", self.scheme.as_str(), host, self.port)
    }
}

/// Reverse-proxy host-specific fields.
#[derive(Debug, Clone, PartialEq, Eq, Serialize, Deserialize)]
pub struct ProxySpec {
    pub upstream: Upstream,
    /// Declared for NPM compatibility; Caddy proxies upgrades natively. The compiler does not
    /// change route behavior for this flag in the foundation slice.
    pub websocket: bool,
    /// Preserve the client Host header. Caddy does this by default; `false` rewrites Host to the
    /// upstream host.
    pub preserve_host: bool,
}

impl ProxySpec {
    pub fn new(upstream: Upstream) -> Self {
        Self {
            upstream,
            websocket: false,
            preserve_host: true,
        }
    }

    fn validate(&self) -> Result<(), CoreError> {
        self.upstream.validate()
    }
}

/// Redirect scheme: auto preserves the request scheme, like NPM's `$scheme`.
#[derive(Debug, Clone, Copy, PartialEq, Eq, Serialize, Deserialize)]
#[serde(rename_all = "snake_case")]
pub enum RedirectScheme {
    Auto,
    Http,
    Https,
}

impl RedirectScheme {
    pub fn as_caddy_placeholder(self) -> &'static str {
        match self {
            Self::Auto => "{http.request.scheme}",
            Self::Http => "http",
            Self::Https => "https",
        }
    }
}

#[derive(Debug, Clone, PartialEq, Eq, Serialize, Deserialize)]
pub struct RedirectSpec {
    pub scheme: RedirectScheme,
    pub target: String,
    pub status: u16,
    pub preserve_path: bool,
}

impl RedirectSpec {
    fn validate(&self) -> Result<(), CoreError> {
        normalize_domain(&self.target)?;
        if !matches!(self.status, 300 | 301 | 302 | 303 | 307 | 308) {
            return Err(CoreError::Invalid(format!(
                "redirect status {} is not supported; expected 300, 301, 302, 303, 307 or 308",
                self.status
            )));
        }
        Ok(())
    }
}

#[derive(Debug, Clone, Copy, PartialEq, Eq, Default, Serialize, Deserialize)]
pub struct DeadSpec;

#[derive(Debug, Clone, PartialEq, Eq, Serialize, Deserialize)]
#[serde(tag = "kind", content = "spec", rename_all = "snake_case")]
pub enum HostSpec {
    Proxy(ProxySpec),
    Redirect(RedirectSpec),
    Dead(DeadSpec),
}

impl HostSpec {
    pub fn kind(&self) -> HostKind {
        match self {
            Self::Proxy(_) => HostKind::Proxy,
            Self::Redirect(_) => HostKind::Redirect,
            Self::Dead(_) => HostKind::Dead,
        }
    }

    fn validate(&self) -> Result<(), CoreError> {
        match self {
            Self::Proxy(spec) => spec.validate(),
            Self::Redirect(spec) => spec.validate(),
            Self::Dead(_) => Ok(()),
        }
    }
}

/// One managed HTTP host. TLS is a separate binding validated against a certificate or policy.
#[derive(Debug, Clone, PartialEq, Eq, Serialize, Deserialize)]
pub struct Host {
    pub id: HostId,
    /// Exact names and wildcard patterns. Normalized by [`Host::validate_structure`].
    pub domains: Vec<String>,
    pub tls: HostTls,
    pub enabled: bool,
    pub spec: HostSpec,
}

impl Host {
    pub fn new(id: HostId, domains: Vec<String>, tls: HostTls, spec: HostSpec) -> Self {
        Self {
            id,
            domains,
            tls,
            enabled: true,
            spec,
        }
    }

    pub fn kind(&self) -> HostKind {
        self.spec.kind()
    }

    /// Validate everything that does not require loading a certificate or policy.
    ///
    /// The compiler and API use this before any coverage check; [`Host::validate`] adds the
    /// certificate/policy coverage checks.
    pub fn validate_structure(&self) -> Result<(), CoreError> {
        if self.id.0 == 0 {
            return Err(CoreError::Invalid(
                "host id must be greater than zero".to_string(),
            ));
        }
        validate_pattern_domains(&self.domains)?;
        self.tls.validate_shape()?;
        self.spec.validate()
    }

    /// Validate the host including its TLS certificate/policy reference.
    pub fn validate(
        &self,
        certificate: Option<&ExplicitCertificate>,
        policy: Option<&AutoCertificatePolicy>,
    ) -> Result<(), CoreError> {
        self.validate_structure()?;
        self.tls.validate(&self.domains, certificate, policy)
    }

    /// Normalized domains in stable order. Call only after validation, or tolerate invalid input
    /// by returning an error.
    pub fn normalized_domains(&self) -> Result<Vec<String>, CoreError> {
        let mut normalized = Vec::with_capacity(self.domains.len());
        for domain in &self.domains {
            normalized.push(normalize_pattern(domain)?);
        }
        Ok(normalized)
    }
}

/// Check that no domain is claimed by two hosts. A host's own duplicate domains are already
/// rejected by [`validate_pattern_domains`].
pub fn validate_host_domain_uniqueness(hosts: &[Host]) -> Result<(), CoreError> {
    let mut seen: BTreeMap<String, HostId> = BTreeMap::new();
    for host in hosts {
        for domain in host.normalized_domains()? {
            if let Some(existing) = seen.insert(domain.clone(), host.id) {
                return Err(CoreError::Invalid(format!(
                    "domain `{domain}` is already used by host {} (also host {})",
                    existing.0, host.id.0
                )));
            }
        }
    }
    Ok(())
}

#[derive(Debug, Error, PartialEq, Eq)]
pub enum CoreError {
    #[error("invalid certificate configuration: {0}")]
    Invalid(String),
    #[error("missing required field: {0}")]
    Missing(&'static str),
    #[error("certificate origin mismatch: expected {expected:?}, got {actual:?}")]
    OriginMismatch {
        expected: CertificateOrigin,
        actual: CertificateOrigin,
    },
    #[error("{origin:?} certificate does not cover host domain(s): {domains:?}")]
    Coverage {
        origin: CertificateOrigin,
        domains: Vec<String>,
    },
}

fn require_non_empty(field: &str, value: &str, max: usize) -> Result<(), CoreError> {
    let trimmed = value.trim();
    if trimmed.is_empty() {
        return Err(CoreError::Invalid(format!("{field} must not be empty")));
    }
    if trimmed.len() > max {
        return Err(CoreError::Invalid(format!(
            "{field} must be at most {max} characters"
        )));
    }
    Ok(())
}

fn validate_pattern_domains(domains: &[String]) -> Result<(), CoreError> {
    if domains.is_empty() {
        return Err(CoreError::Invalid(
            "at least one domain is required".to_string(),
        ));
    }
    if domains.len() > 100 {
        return Err(CoreError::Invalid(
            "at most 100 domains are supported".to_string(),
        ));
    }
    let mut seen = BTreeSet::new();
    for domain in domains {
        let normalized = normalize_pattern(domain)?;
        if !seen.insert(normalized.clone()) {
            return Err(CoreError::Invalid(format!(
                "duplicate domain `{normalized}`"
            )));
        }
    }
    Ok(())
}

fn validate_certificate_domains(domains: &[String]) -> Result<(), CoreError> {
    if domains.is_empty() {
        return Err(CoreError::Invalid(
            "at least one certificate domain is required".to_string(),
        ));
    }
    if domains.len() > 100 {
        return Err(CoreError::Invalid(
            "at most 100 certificate domains are supported".to_string(),
        ));
    }
    let mut seen = BTreeSet::new();
    for domain in domains {
        let normalized = normalize_pattern(domain)?;
        if !seen.insert(normalized.clone()) {
            return Err(CoreError::Invalid(format!(
                "duplicate certificate domain `{normalized}`"
            )));
        }
    }
    Ok(())
}

/// Normalize and validate a certificate/host domain. IDNA is deliberately not implemented; names
/// must already be ASCII/punycode.
pub fn normalize_domain(value: &str) -> Result<String, CoreError> {
    let value = value.trim().trim_end_matches('.').to_ascii_lowercase();
    if value.is_empty() {
        return Err(CoreError::Invalid("domain must not be empty".to_string()));
    }
    if value.len() > 253 {
        return Err(CoreError::Invalid(format!(
            "domain `{value}` exceeds 253 characters"
        )));
    }
    if value.starts_with("*.") {
        return Err(CoreError::Invalid(format!(
            "wildcard `{value}` is only valid in a certificate policy subject"
        )));
    }
    validate_labels(&value)?;
    Ok(value)
}

/// Normalize a policy subject, allowing one left-most `*` label.
pub fn normalize_pattern(value: &str) -> Result<String, CoreError> {
    let value = value.trim().trim_end_matches('.').to_ascii_lowercase();
    if value.len() > 253 {
        return Err(CoreError::Invalid(format!(
            "domain `{value}` exceeds 253 characters"
        )));
    }
    if let Some(suffix) = value.strip_prefix("*.") {
        if suffix.is_empty() || suffix.contains('*') {
            return Err(CoreError::Invalid(format!(
                "invalid wildcard subject `{value}`"
            )));
        }
        validate_labels(suffix)?;
        if !suffix.contains('.') {
            return Err(CoreError::Invalid(format!(
                "wildcard subject `{value}` needs a registrable suffix"
            )));
        }
        return Ok(format!("*.{suffix}"));
    }
    if value.contains('*') {
        return Err(CoreError::Invalid(format!(
            "wildcard is only supported as the left-most label in `{value}`"
        )));
    }
    normalize_domain(&value)
}

fn validate_labels(value: &str) -> Result<(), CoreError> {
    if value.is_empty() {
        return Err(CoreError::Invalid("domain must not be empty".to_string()));
    }
    for label in value.split('.') {
        if label.is_empty() || label.len() > 63 {
            return Err(CoreError::Invalid(format!(
                "domain `{value}` has an invalid label"
            )));
        }
        if label.starts_with('-') || label.ends_with('-') {
            return Err(CoreError::Invalid(format!(
                "domain `{value}` has a label starting or ending with '-'"
            )));
        }
        if !label
            .bytes()
            .all(|byte| byte.is_ascii_alphanumeric() || byte == b'-')
        {
            return Err(CoreError::Invalid(format!(
                "domain `{value}` contains an unsupported character"
            )));
        }
    }
    Ok(())
}

fn certificate_covers(domains: &[String], host_domain: &str) -> bool {
    domains
        .iter()
        .any(|domain| pattern_covers(domain, host_domain))
}

/// Whether a policy/certificate pattern covers a host pattern. Exact names match only the same
/// name; `*.example.com` covers `*.example.com` and exactly one label below it.
fn pattern_covers(covering: &str, target: &str) -> bool {
    let (Ok(covering), Ok(target)) = (normalize_pattern(covering), normalize_pattern(target))
    else {
        return false;
    };
    if covering == target {
        return true;
    }
    let Some(suffix) = covering.strip_prefix("*.") else {
        return false;
    };
    if let Some(target_suffix) = target.strip_prefix("*.") {
        return target_suffix == suffix;
    }
    let Some(label) = target
        .strip_suffix(suffix)
        .and_then(|prefix| prefix.strip_suffix('.'))
    else {
        return false;
    };
    !label.is_empty() && !label.contains('.')
}

#[cfg(test)]
mod tests {
    use super::*;

    fn policy() -> AutoCertificatePolicy {
        AutoCertificatePolicy {
            id: PolicyId(4),
            name: "tenant wildcard".to_string(),
            subjects: vec!["*.example.com".to_string(), "example.com".to_string()],
            mode: AutoMode::OnDemand,
            issuer: Some("acme".to_string()),
            key_type: Some(KeyType::P256),
            renewal_window_ratio: Some(0.33),
            enabled: true,
        }
    }

    fn manual_certificate() -> ExplicitCertificate {
        ExplicitCertificate {
            id: CertificateId(7),
            origin: CertificateOrigin::Manual,
            domains: vec!["example.com".to_string(), "www.example.com".to_string()],
            status: CertificateStatus::Issued,
            expires_at_unix: Some(1_800_000_000),
            storage_ref: Some("manual/7".to_string()),
        }
    }

    #[test]
    fn origin_labels_and_binding_rules_are_explicit() {
        assert_eq!(CertificateOrigin::AutoGenerated.label(), "Auto-generated");
        assert_eq!(CertificateOrigin::AutoGenerated.as_str(), "auto_generated");
        assert!(CertificateOrigin::AutoGenerated.is_auto_generated());
        assert!(!CertificateOrigin::AutoGenerated.bindable_by_id());
        assert!(CertificateOrigin::Manual.bindable_by_id());
        assert_eq!(
            CertificateOrigin::AcmeConfigured.label(),
            "ACME (configured)"
        );
    }

    #[test]
    fn wildcard_matches_exactly_one_label() {
        let policy = policy();
        assert!(policy.matches("api.example.com"));
        assert!(policy.matches("example.com"));
        assert!(!policy.matches("a.b.example.com"));
        assert!(!policy.matches("example.net"));
        assert!(!policy.matches("api.example.com:443"));
    }

    #[test]
    fn policy_validation_rejects_bad_subjects_and_ratios() {
        let mut candidate = policy();
        candidate.subjects = vec![];
        assert!(matches!(candidate.validate(), Err(CoreError::Invalid(_))));

        let mut candidate = policy();
        candidate.subjects = vec!["*.*.example.com".to_string()];
        assert!(matches!(candidate.validate(), Err(CoreError::Invalid(_))));

        let mut candidate = policy();
        candidate.renewal_window_ratio = Some(1.0);
        assert!(matches!(candidate.validate(), Err(CoreError::Invalid(_))));

        let mut candidate = policy();
        candidate.name = " ".to_string();
        assert!(matches!(candidate.validate(), Err(CoreError::Invalid(_))));
    }

    #[test]
    fn policy_covers_all_host_domains() {
        let policy = policy();
        assert!(policy.covers_all(&["a.example.com".to_string(), "b.example.com".to_string()]));
        assert!(!policy.covers_all(&["a.other.com".to_string()]));
        assert!(!policy.covers_all(&[]));
    }

    #[test]
    fn explicit_origins_require_their_own_metadata() {
        let manual = manual_certificate();
        assert!(manual.validate().is_ok());

        let mut missing_storage = manual.clone();
        missing_storage.storage_ref = None;
        assert!(matches!(
            missing_storage.validate(),
            Err(CoreError::Invalid(_))
        ));

        let auto_as_explicit = ExplicitCertificate {
            origin: CertificateOrigin::AutoGenerated,
            ..manual
        };
        assert!(matches!(
            auto_as_explicit.validate(),
            Err(CoreError::Invalid(_))
        ));
    }

    #[test]
    fn host_auto_binding_requires_policy_coverage_and_no_certificate_id() {
        let policy = policy();
        let binding = HostTls::for_auto(PolicyId(4));
        assert!(binding
            .validate(&["api.example.com".to_string()], None, Some(&policy))
            .is_ok());

        let mut wrong_policy = binding.clone();
        wrong_policy.auto_policy_id = Some(PolicyId(5));
        assert!(matches!(
            wrong_policy.validate(&["api.example.com".to_string()], None, Some(&policy)),
            Err(CoreError::Invalid(_))
        ));

        let mut with_cert = binding.clone();
        with_cert.certificate_id = Some(CertificateId(7));
        assert!(matches!(
            with_cert.validate(&["api.example.com".to_string()], None, Some(&policy)),
            Err(CoreError::Invalid(_))
        ));

        let uncovered = binding;
        assert!(matches!(
            uncovered.validate(&["api.other.com".to_string()], None, Some(&policy)),
            Err(CoreError::Coverage { .. })
        ));
    }

    #[test]
    fn host_manual_binding_rejects_cross_origin_and_missing_coverage() {
        let certificate = manual_certificate();
        let binding = HostTls::for_explicit(CertificateId(7), CertificateOrigin::Manual);
        assert!(binding
            .validate(&["www.example.com".to_string()], Some(&certificate), None)
            .is_ok());

        let acme_binding =
            HostTls::for_explicit(CertificateId(7), CertificateOrigin::AcmeConfigured);
        assert!(matches!(
            acme_binding.validate(&["www.example.com".to_string()], Some(&certificate), None),
            Err(CoreError::OriginMismatch { .. })
        ));

        assert!(matches!(
            binding.validate(&["other.example.com".to_string()], Some(&certificate), None),
            Err(CoreError::Coverage { .. })
        ));
    }

    #[test]
    fn disabled_tls_cannot_carry_ssl_flags_or_ids() {
        let mut binding = HostTls::disabled();
        binding.ssl_forced = true;
        assert!(matches!(
            binding.validate(&["example.com".to_string()], None, None),
            Err(CoreError::Invalid(_))
        ));

        let mut binding = HostTls::disabled();
        binding.certificate_id = Some(CertificateId(1));
        assert!(matches!(
            binding.validate(&["example.com".to_string()], None, None),
            Err(CoreError::Invalid(_))
        ));
    }

    #[test]
    fn hsts_requires_forced_ssl() {
        let mut binding = HostTls::disabled();
        binding.hsts_enabled = true;
        assert!(matches!(
            binding.validate(&["example.com".to_string()], None, None),
            Err(CoreError::Invalid(_))
        ));

        let mut binding = HostTls::disabled();
        binding.hsts_subdomains = true;
        assert!(matches!(
            binding.validate(&["example.com".to_string()], None, None),
            Err(CoreError::Invalid(_))
        ));
    }

    #[test]
    fn records_are_tagged_by_origin_for_read_models() {
        let manual = CertificateRecord::Explicit(manual_certificate());
        assert_eq!(manual.origin(), CertificateOrigin::Manual);
        assert!(!manual.is_read_only());
        assert_eq!(manual.domains(), ["example.com", "www.example.com"]);

        let auto = CertificateRecord::Auto(AutoCertificate {
            uid: "auto:4:api.example.com".to_string(),
            policy_id: PolicyId(4),
            domains: vec!["api.example.com".to_string()],
            status: CertificateStatus::Issued,
            expires_at_unix: Some(1_800_000_000),
            storage_ref: Some("certificates/acme/example".to_string()),
        });
        assert_eq!(auto.origin(), CertificateOrigin::AutoGenerated);
        assert!(auto.is_read_only());
        assert!(auto.validate().is_ok());
        assert!(auto.display_name().starts_with("Auto-generated"));
    }

    #[test]
    fn wildcard_explicit_certificate_covers_one_label() {
        let certificate = ExplicitCertificate {
            id: CertificateId(9),
            origin: CertificateOrigin::AcmeConfigured,
            domains: vec!["*.example.com".to_string()],
            status: CertificateStatus::Issued,
            expires_at_unix: Some(1_800_000_000),
            storage_ref: Some("acme/9".to_string()),
        };
        assert!(certificate.validate().is_ok());
        assert!(certificate.covers_all(&["api.example.com".to_string()]));
        assert!(!certificate.covers_all(&["a.b.example.com".to_string()]));
        assert!(!certificate.covers_all(&["example.com".to_string()]));
    }

    #[test]
    fn disabled_auto_policy_cannot_be_bound() {
        let mut policy = policy();
        policy.enabled = false;
        let binding = HostTls::for_auto(PolicyId(4));
        assert!(matches!(
            binding.validate(&["api.example.com".to_string()], None, Some(&policy)),
            Err(CoreError::Invalid(_))
        ));
    }

    #[test]
    fn explicit_record_display_name_includes_origin() {
        let record = CertificateRecord::Explicit(manual_certificate());
        let name = record.display_name();
        assert!(name.starts_with("Manual — "));
        assert!(name.contains("example.com"));
    }

    #[test]
    fn wildcard_hosts_are_covered_by_a_matching_policy() {
        let policy = policy();
        assert!(policy.matches("*.example.com"));
        assert!(!policy.matches("*.other.com"));
        assert!(policy.covers_all(&["*.example.com".to_string()]));

        let exact = AutoCertificatePolicy {
            subjects: vec!["example.com".to_string()],
            ..policy
        };
        assert!(!exact.matches("*.example.com"));
    }

    #[test]
    fn wildcard_certificate_covers_a_wildcard_host() {
        let certificate = ExplicitCertificate {
            id: CertificateId(10),
            origin: CertificateOrigin::AcmeConfigured,
            domains: vec!["*.example.com".to_string()],
            status: CertificateStatus::Issued,
            expires_at_unix: None,
            storage_ref: None,
        };
        assert!(certificate.covers_all(&["*.example.com".to_string()]));
        assert!(certificate.covers_all(&["api.example.com".to_string()]));
        assert!(!certificate.covers_all(&["example.com".to_string()]));
    }

    #[test]
    fn read_model_view_carries_explicit_origin() {
        let manual = CertificateRecord::Explicit(manual_certificate());
        let view = manual.view();
        assert_eq!(view.origin, CertificateOrigin::Manual);
        assert_eq!(view.uid, "7");
        assert!(view.policy_id.is_none());
        assert!(!view.read_only);
        let json = serde_json::to_value(&view).expect("json");
        assert_eq!(json["origin"], "manual");

        let auto = CertificateRecord::Auto(AutoCertificate {
            uid: "auto:4:api.example.com".to_string(),
            policy_id: PolicyId(4),
            domains: vec!["api.example.com".to_string()],
            status: CertificateStatus::Issued,
            expires_at_unix: None,
            storage_ref: None,
        });
        let view = auto.view();
        assert_eq!(view.origin, CertificateOrigin::AutoGenerated);
        assert_eq!(view.policy_id, Some(PolicyId(4)));
        assert!(view.read_only);
    }

    #[test]
    fn overlong_wildcard_names_are_rejected_everywhere() {
        let overlong = format!("*.{}", vec!["a".repeat(63); 5].join("."));
        assert!(overlong.len() > 253);
        assert!(normalize_pattern(&overlong).is_err());

        let mut candidate = policy();
        candidate.subjects = vec![overlong.clone()];
        assert!(matches!(candidate.validate(), Err(CoreError::Invalid(_))));

        let certificate = ExplicitCertificate {
            id: CertificateId(11),
            origin: CertificateOrigin::AcmeConfigured,
            domains: vec![overlong.clone()],
            status: CertificateStatus::Issued,
            expires_at_unix: None,
            storage_ref: None,
        };
        assert!(matches!(certificate.validate(), Err(CoreError::Invalid(_))));
        assert!(matches!(
            HostTls::for_auto(PolicyId(4)).validate(&[overlong], None, Some(&policy())),
            Err(CoreError::Invalid(_))
        ));
    }

    #[test]
    fn host_binding_rejects_stray_certificate_or_policy_objects() {
        let certificate = manual_certificate();
        let policy = policy();

        assert!(matches!(
            HostTls::for_auto(PolicyId(4)).validate(
                &["api.example.com".to_string()],
                Some(&certificate),
                Some(&policy)
            ),
            Err(CoreError::Invalid(_))
        ));

        assert!(matches!(
            HostTls::for_explicit(CertificateId(7), CertificateOrigin::Manual).validate(
                &["example.com".to_string()],
                Some(&certificate),
                Some(&policy)
            ),
            Err(CoreError::Invalid(_))
        ));

        assert!(matches!(
            HostTls::disabled().validate(&["example.com".to_string()], Some(&certificate), None),
            Err(CoreError::Invalid(_))
        ));
    }

    #[test]
    fn serde_uses_stable_snake_case_origin_names() {
        let json = serde_json::to_value(CertificateOrigin::AutoGenerated).expect("json");
        assert_eq!(json, serde_json::json!("auto_generated"));
        let parsed: CertificateOrigin =
            serde_json::from_value(serde_json::json!("acme_configured")).expect("parse");
        assert_eq!(parsed, CertificateOrigin::AcmeConfigured);
    }
    fn proxy_host_for_tests(id: u64, domains: &[&str]) -> Host {
        Host::new(
            HostId(id),
            domains.iter().map(|value| value.to_string()).collect(),
            HostTls::disabled(),
            HostSpec::Proxy(ProxySpec::new(Upstream::new(
                UpstreamScheme::Http,
                "10.0.0.5",
                8080,
            ))),
        )
    }

    #[test]
    fn host_structure_accepts_proxy_and_wildcard_domains() {
        let host = proxy_host_for_tests(1, &["example.com", "*.example.com"]);
        assert_eq!(host.kind(), HostKind::Proxy);
        host.validate_structure().expect("valid host");
        assert_eq!(
            host.normalized_domains().expect("domains"),
            vec!["example.com".to_string(), "*.example.com".to_string()]
        );
    }

    #[test]
    fn host_structure_rejects_zero_id_and_empty_domains() {
        let mut host = proxy_host_for_tests(1, &["example.com"]);
        host.id = HostId(0);
        assert!(matches!(
            host.validate_structure(),
            Err(CoreError::Invalid(_))
        ));

        let mut host = proxy_host_for_tests(1, &["example.com"]);
        host.domains.clear();
        assert!(matches!(
            host.validate_structure(),
            Err(CoreError::Invalid(_))
        ));
    }

    #[test]
    fn upstream_validation_rejects_scheme_path_and_zero_port() {
        let mut spec = ProxySpec::new(Upstream::new(UpstreamScheme::Http, "10.0.0.5", 8080));
        spec.upstream.host = "http://10.0.0.5".to_string();
        assert!(spec.validate().is_err());

        let mut spec = ProxySpec::new(Upstream::new(UpstreamScheme::Http, "10.0.0.5", 8080));
        spec.upstream.host = "10.0.0.5/path".to_string();
        assert!(spec.validate().is_err());

        let mut spec = ProxySpec::new(Upstream::new(UpstreamScheme::Http, "10.0.0.5", 8080));
        spec.upstream.port = 0;
        assert!(spec.validate().is_err());
    }

    #[test]
    fn redirect_validation_rejects_bad_status_and_wildcard_target() {
        let mut spec = RedirectSpec {
            scheme: RedirectScheme::Auto,
            target: "new.example.com".to_string(),
            status: 301,
            preserve_path: true,
        };
        spec.validate().expect("valid redirect");
        spec.status = 200;
        assert!(spec.validate().is_err());
        spec.status = 301;
        spec.target = "*.example.com".to_string();
        assert!(spec.validate().is_err());
    }

    #[test]
    fn host_domain_uniqueness_rejects_duplicates_across_hosts() {
        let first = proxy_host_for_tests(1, &["example.com"]);
        let second = proxy_host_for_tests(2, &["example.com"]);
        assert!(validate_host_domain_uniqueness(&[first, second]).is_err());
    }

    #[test]
    fn ipv6_upstream_is_bracketed_in_dial_and_validated() {
        let upstream = Upstream::new(UpstreamScheme::Https, "2001:db8::5", 8443);
        upstream.validate().expect("valid IPv6");
        assert_eq!(upstream.dial(), "https://[2001:db8::5]:8443");

        let upstream = Upstream::new(UpstreamScheme::Https, "[2001:db8::5]", 8443);
        upstream.validate().expect("bracketed IPv6");
        assert_eq!(upstream.dial(), "https://[2001:db8::5]:8443");

        let upstream = Upstream::new(UpstreamScheme::Http, "not:ipv6", 8080);
        assert!(upstream.validate().is_err());
    }

    #[test]
    fn host_spec_round_trips_through_json() {
        for spec in [
            HostSpec::Proxy(ProxySpec::new(Upstream::new(
                UpstreamScheme::Http,
                "10.0.0.5",
                8080,
            ))),
            HostSpec::Redirect(RedirectSpec {
                scheme: RedirectScheme::Https,
                target: "new.example.com".to_string(),
                status: 308,
                preserve_path: false,
            }),
            HostSpec::Dead(DeadSpec),
        ] {
            let value = serde_json::to_value(&spec).expect("serialize");
            let parsed: HostSpec = serde_json::from_value(value).expect("deserialize");
            assert_eq!(parsed, spec);
        }
    }

    #[test]
    fn host_tls_shape_requires_the_matching_reference() {
        let mut tls = HostTls::disabled();
        tls.ssl_forced = true;
        assert!(matches!(tls.validate_shape(), Err(CoreError::Invalid(_))));

        let mut tls = HostTls::for_auto(PolicyId(4));
        tls.auto_policy_id = None;
        assert!(matches!(
            tls.validate_shape(),
            Err(CoreError::Missing("auto_policy_id"))
        ));

        let mut tls = HostTls::for_explicit(CertificateId(7), CertificateOrigin::Manual);
        tls.certificate_id = None;
        assert!(matches!(
            tls.validate_shape(),
            Err(CoreError::Missing("certificate_id"))
        ));
    }

    #[test]
    fn host_validate_still_checks_certificate_coverage() {
        let mut tls = HostTls::for_explicit(CertificateId(7), CertificateOrigin::Manual);
        tls.ssl_forced = false;
        let host = Host::new(
            HostId(1),
            vec!["other.example.com".to_string()],
            tls,
            HostSpec::Proxy(ProxySpec::new(Upstream::new(
                UpstreamScheme::Http,
                "10.0.0.5",
                8080,
            ))),
        );
        let certificate = ExplicitCertificate {
            id: CertificateId(7),
            origin: CertificateOrigin::Manual,
            domains: vec!["example.com".to_string()],
            status: CertificateStatus::Issued,
            expires_at_unix: Some(1_800_000_000),
            storage_ref: Some("manual/7".to_string()),
        };
        assert!(matches!(
            host.validate(Some(&certificate), None),
            Err(CoreError::Coverage { .. })
        ));
    }
}
